const { vec } = NMath;
const K = 10;
const iterations = 8;
const grid = 28;
const threshold = 0.05;

const samples = await IO.loadMNIST();

// An image is a density: pixels above the threshold are points in [0,1]^2 weighted by intensity.
const coordinates = Array.from({ length: grid * grid }, (_, i) =>
    vec((i % grid + 0.5) / grid, 1 - (Math.floor(i / grid) + 0.5) / grid));
const toCloud = image => {
    const points = [], weights = [];
    image.components.forEach((value, i) => {
        if (value > threshold) { points.push(coordinates[i]); weights.push(value); }
    });
    if (points.length === 0) return null;
    const total = weights.reduce((sum, w) => sum + w, 0);
    return { points, weights: weights.map(w => w / total) };
};

// 2-Wasserstein distance between two images seen as densities.
const wasserstein = (a, b) => {
    const source = toCloud(a), target = toCloud(b);
    if (!source || !target) return 1;
    return OptimalTransport.wasserstein(source, target, { entropy: 0.01, maxIterations: 200 });
};

const kmeans = Kmeans.new(samples, K, { distance: wasserstein }).init();
for (let i = 0; i < iterations; i++) {
    kmeans.update();
    console.log(`Iteration ${i + 1}/${iterations}`);
    // Yield so the page stays responsive during the long computation.
    await new Promise(resolve => setTimeout(resolve));
}

const means = Array.from({ length: K }, () => new Float32Array(28 * 28));
const counts = new Array(K).fill(0);
samples.forEach(image => {
    const cluster = kmeans.predictIndex(image);
    counts[cluster]++;
    for (let i = 0; i < 28 * 28; i++) means[cluster][i] += image[i];
});
means.forEach((mean, cluster) => {
    for (let i = 0; i < mean.length; i++) mean[i] /= Math.max(1, counts[cluster]);
});
console.log(`Cluster sizes: ${counts.join(", ")}`);
IO.paintMNIST(means, 5);
